"""Migrated Meridian CRM 4.2 order_fulfilment workflow."""

from typing import Any


def _lookup_credit_hold(record: dict[str, Any], tables: dict[str, Any]) -> str:
    """Return CRED_HOLD from the first live ACCT_MASTER row matching ACCT_ID."""
    account_id = record.get("ACCT_ID", "")
    rows = tables.get("ACCT_MASTER", [])

    if not isinstance(rows, list):
        return ""

    for row in rows:
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            value = row.get("CRED_HOLD", "")
            return "" if value is None else str(value)

    return ""


def _positive_total(record: dict[str, Any]) -> bool:
    """Implement NVL(TOT_AMT, 0) > 0 for the values relevant to this workflow."""
    value = record.get("TOT_AMT", 0)
    if value is None or value == "":
        value = 0

    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order_fulfilment workflow transition."""
    new_record = dict(record)

    if state == "E" and event == "approve" and _positive_total(record):
        return {
            "state": "A",
            "record": new_record,
            "audits": ["ORD_APPR"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": new_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": new_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if (
        state == "A"
        and event == "cancel"
        and _lookup_credit_hold(record, tables) != "Y"
    ):
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": new_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
